// 1. 스타일을 주입하는 함수 정의
const injectShadowStyle = (host) => {
  // 이미 스타일이 주입되었는지 확인 (중복 방지)
  if (host.shadowRoot.querySelector('#custom-injected-style')) return;

  const style = document.createElement('style');
  style.id = 'custom-injected-style'; // 식별자 추가
  style.textContent = `
    .review-selector-card {
      border: 2px solid red !important;
      background: yellow !important;
    }
  `;
  
  // 쉐도우 루트에 스타일 추가
  host.shadowRoot.appendChild(style);
  console.log('✅ Shadow DOM에 스타일이 성공적으로 주입되었습니다.');
};

// 2. MutationObserver 설정
const observer = new MutationObserver((mutations) => {
  mutations.forEach((mutation) => {
    // 추가된 노드들을 확인
    mutation.addedNodes.forEach((node) => {
      // 노드 타입이 ELEMENT_NODE(1)이고 태그 이름이 일치하는지 확인
      if (node.nodeType === 1 && node.tagName.toLowerCase() === 'review-custom-fixed-overlay') {
        injectShadowStyle(node);
      }
      
      // 만약 노드 내부 깊숙이 추가되는 경우를 대비해 하위 탐색
      if (node.nodeType === 1 && node.querySelector) {
        const found = node.querySelector('review-custom-fixed-overlay');
        if (found) injectShadowStyle(found);
      }
    });
  });
});

// 3. 감시 시작 (body 전체를 감시하여 유연하게 대응)
observer.observe(document.body, {
  childList: true,
  subtree: true
});

